def stratified_sample(logs, target, seed=7):
    rng = random.Random(seed)
    groups = defaultdict(list)
    for x in logs:
        groups[(x["intent"], x["lang"])].append(x)
    sample = []
    for key, group in groups.items():
        k = round(target * len(group) / len(logs))
        sample += rng.sample(group, min(k, len(group)))
    return sample

usersim.code:
def run(card, agent, sim, max_turns=12):
    msg = sim.first_message(card, SIM_RULES)
    for _ in range(max_turns):
        reply = agent.respond(msg)
        msg = sim.respond(reply)
        if "DONE" in msg:
            break
    return "refund" in reply.lower()

